    'ro.pyramidTitle': 'A model built from scratch, for comparison',
    'ro.pyramidNote': 'Mining, which ignores the rules above and starts from the access',
    'ro.pyramidLead': 'With people and contracts available, rules are mined against the organisation\u2019s own attributes instead of guessed from what travels together: {rules} rules over {levels}, granting {grants} entitlements and explaining {coverage} of all access. Each one already carries the condition that selects its group, and rules stack, so nothing granted higher up is repeated below.',
    'ro.openPyramid': 'Open Mining',
    'ro.bundlesSecondary': 'Entitlement bundles are still mined for the rows the pyramid cannot place \u2014 they appear as explanations rather than as rules, because a bundle has no condition of its own.',
