    'ro.loadVault': 'Load a vault export to mine rules with conditions instead',
    'py.needsVault': 'The pyramid orders the attributes HR maintains \u2014 department, job title, location \u2014 and needs the vault export to read them. Without it, the fallback below mines entitlements that travel together, which finds real bundles but cannot say who should get them.',
