    'fi.correlate-former-employee.why': 'Correlation is the first thing that breaks when someone leaves the source, so a leaver\u2019s account arrives here as an orphan with no trace of who it was. Naming the person is what makes it actionable.',
    'fi.correlate-former-employee.fix': 'Confirm the match, then apply the leaver process: disable what is still enabled and remove the entitlements, licence groups first.',
