    'fi.correlate-current-employee.fix': 'Confirm the match and correlate it in HelloID, so the account follows the person from now on.',
    'fi.correlate-current-employee.detail': '{person} · matched on {evidence}',

    'fi.correlate-secondary-account.title': 'Admin and function accounts with no owner of their own',
    'fi.correlate-secondary-account.what': '{n} account(s) across {p} person(s) sit alongside a personal account that belongs to the same individual.',
    'fi.correlate-secondary-account.why': 'A second account rarely has its own person record, so reconciliation reports it as ownerless. It is not: the owner is the person holding the main account, which is who should be recertifying and losing it on departure.',
    'fi.correlate-secondary-account.fix': 'Correlate the secondary account to the same person in HelloID, so it follows their lifecycle instead of standing alone.',
    'fi.correlate-secondary-account.detail': '{cls} for {person} · main account {main}',
