    'fi.nedap-unresolved.what': '{n} name(s) in the mapping rows do not appear in the lookup lists, so their IDs cannot be resolved.',
    'fi.nedap-unresolved.why': 'The connector CSVs carry IDs; a row with an unresolvable name is dropped from the export and the entitlement silently never arrives in Nedap.',
    'fi.nedap-unresolved.fix': 'Fix the spelling in the mapping row or add the missing entry to the lookup list, then re-export the CSVs.',
    'fi.nedap-lint.title': 'Nedap mapping rows that need attention',
    'fi.nedap-lint.what': '{n} mapping row(s) are redundant, duplicated, conflicting or unknown to the imported HR data.',
    'fi.nedap-lint.why': 'Each one is a rule that does not do what its author intended: it grants nothing, is swallowed by a wildcard, or references a department or title HR does not know.',
    'fi.nedap-lint.fix': 'Review them in the Nedap ONS workbench health tab; the message per row says what to change.',

    'fi.privileged-orphan.title': 'Enabled accounts with privileged access and no owner',
    'fi.privileged-orphan.what': '{n} enabled account(s) hold admin, PAM or server groups but are not linked to a person in HelloID.',
    'fi.privileged-orphan.why': 'No person is linked to these accounts, so no employment event can trigger review or removal of their privileged access, and use of that access cannot be attributed to a named individual from this data.',
    'fi.privileged-orphan.fix': 'Record an owner for each account, or bring it under a managed service-account process. Where no owner can be established, decide explicitly whether the account should remain enabled.',

    'fi.enabled-orphan.title': 'Enabled accounts not managed by HelloID',
    'fi.enabled-orphan.what': '{n} enabled account(s) exist in the target system with no linked person.',
    'fi.enabled-orphan.why': 'These accounts can authenticate, but no person is attached to them in HelloID, so no joiner-mover-leaver event applies to them.',
    'fi.enabled-orphan.fix': 'Match to a person, convert to a managed service account, or disable. Set the reconciliation resolution to Excluded for the ones that are legitimately out of scope.',

    'fi.external-accounts.title': 'Active vendor / contractor accounts',
    'fi.external-accounts.what': '{n} enabled account(s) match external-party naming.',
    'fi.external-accounts.why': 'The account name points to a party outside the organisation. This export does not show whether an end date is recorded for them anywhere.',
    'fi.external-accounts.fix': 'Confirm per account whether the engagement is still running, and where it is, record an end date and an internal contact that HelloID can act on.',

    'fi.test-accounts.title': 'Enabled test / demo accounts',
    'fi.test-accounts.what': '{n} enabled account(s) look like test or demo identities.',
    'fi.test-accounts.why': 'The naming suggests a temporary purpose, but this export does not show what these accounts are used for or whether they are still needed.',
    'fi.test-accounts.fix': 'Confirm the current purpose of each; where it has passed, disable the account.',

    'fi.service-unmanaged.title': 'Service accounts outside the IAM model',
    'fi.service-unmanaged.what': '{n} service account(s) have no owner record.',
    'fi.service-unmanaged.why': 'No owner is recorded for these accounts, so this export cannot show who to consult before their credentials or entitlements are changed.',
    'fi.service-unmanaged.fix': 'Register each one against an owning team and a documented purpose; exclude them from person-based reconciliation explicitly.',

    'fi.disabled-licensed.title': 'Disabled accounts still consuming paid licences',
    'fi.disabled-licensed.what': '{n} disabled account(s) still sit in licence-bearing groups.',
    'fi.disabled-licensed.why': 'Disabling an account does not remove its group memberships. Where licences are assigned through these groups, the assignment stays in place until the membership is removed.',
    'fi.disabled-licensed.fix': 'Remove licence groups as part of disabling an account, and check against the licence administration whether these assignments are still being billed.',

    'fi.disabled-entitled.title': 'Disabled accounts retaining entitlements',
    'fi.disabled-entitled.what': '{n} disabled account(s) keep group memberships.',
    'fi.disabled-entitled.why': 'The memberships stay on the account, so re-enabling it restores the same access without a new grant being recorded.',
    'fi.disabled-entitled.fix': 'Remove group memberships when disabling an account, keeping a record of what was removed.',

    'fi.privileged-unmanaged.title': 'Privileged groups assigned outside the IAM model',
    'fi.privileged-unmanaged.what': '{a} assignment(s) across {g} privileged group(s) are not driven by a HelloID business rule.',
    'fi.privileged-unmanaged.why': 'These memberships are not driven by a HelloID business rule, so HelloID will neither re-apply nor withdraw them when a person’s role changes.',
    'fi.privileged-unmanaged.fix': 'Decide per group whether it should be modelled as a HelloID entitlement with a business rule, or handled through a request flow outside it.',

    'fi.security-control-gap.title': 'Security baseline not applied to every active user',
