    'ro.pyramidLead': 'Met mensen en contracten beschikbaar worden regels gedolven tegen de eigen attributen van de organisatie in plaats van geraden uit wat samen voorkomt: {rules} regels over {levels}, samen goed voor {grants} rechten en {coverage} van alle toegang. Elke regel draagt zijn eigen voorwaarde al bij zich, en regels stapelen, dus wat hoger is toegekend wordt eronder niet herhaald.',
