    'py.cfExplain': 'De piramide nest: een functie kan alleen binnen een afdeling gedolven worden. Dat leest zoals een organisatie zichzelf beschrijft, maar het kost dekking waar toegang een functie door de hele organisatie volgt. De dekking-eerst-set negeert de hiërarchie en neemt steeds de voorwaarde die het meeste nog verklaart: minder structuur, meer dekking.',
