    'py.blNoneReconOnly': 'Deze import is een reconciliatie zonder de toegekende rechten ernaast, en een reconciliatie bevat alleen verschillen. Wat een regel al aan iedereen geeft ontbreekt er per definitie in, en dat is meestal waarom er geen basis verschijnt. Importeer de toegekende rechten om het doelsysteem in zijn geheel te zien.',
