    'fi.nedap-uncovered.why': 'De HelloID Nedap-connector kent bereik toe op basis van deze regels; wie op geen regel matcht krijgt geen teams en geen locaties — inloggen lukt, maar er is niets te zien, en niemand wordt gewaarschuwd.',
