    'fi.service-unmanaged.fix': 'Registreer per account een verantwoordelijk team en een vastgelegd doel; sluit ze expliciet uit van reconciliatie op persoon.',

    'fi.disabled-licensed.title': 'Uitgeschakelde accounts die nog betaalde licenties gebruiken',
